head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");

//#include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.gReqAcptNo; // 조회공시 요구접수번호
scwin.gAnsAcptNo; // 조회공시 답변접수번호

// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
// 
// ********************************************************************

scwin.gAcptNo;
scwin.gAnsRnd;
scwin.gAnsFormCd;
scwin.gAnsFormVer;
scwin.gIsurCd;
scwin.vScrenID = 'ULDSTF30201.xml';X < !정보--;
셋팅-- > function() {
    scwin.gReqAcptNo = $c.frame.path("../").scwin.gReqAcptNo;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    //alert(gReqAcptNo);

} < !정보--;
데이타;
읽어오기-- > function() {
    var url = "/InquiryDisclosure.do?method=listInquiryDsclAns&inputMessageId=INQDISCLSANSLIST_INOUT" + "&outputMessageId=INQDISCLSANSLIST_INOUT" + "&REQ_ACPT_NO=" + scwin.gReqAcptNo + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_inquiryans_info.DataID = encodeURI(url);
    dts_inquiryans_info.reset();
};
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gReqAcptNo = dts_inquiryans_info.getCellData(eval(obj), "REQ_ACPT_NO");
    scwin.gAnsRnd = dts_inquiryans_info.getCellData(eval(obj), "ANS_RND");
    scwin.gAnsAcptNo = dts_inquiryans_info.getCellData(eval(obj), "ANS_ACPT_NO");
    scwin.gAnsFormCd = dts_inquiryans_info.getCellData(eval(obj), "ANS_FORM_CD");
    scwin.gAnsFormVer = dts_inquiryans_info.getCellData(eval(obj), "ANS_FORM_VER");
    scwin.gIsurCd = dts_inquiryans_info.getCellData(eval(obj), "ISUR_CD");
    scwin.gAcptNo = scwin.gAnsAcptNo;
    //alert("부모창:"+gIsurCd);

};
scwin.dts_inquiryans_info_OnLoadError = function() {
    $c.stf.alert_error(dts_inquiryans_info);
};
scwin.btn_Close_onclick = async function() {
    //self.close();
    await $c.frame.CloseFrame();
};
scwin.grd_inquiryans_info_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "ANS_DOC_TITLE") {
        $c.stf.fn_OpenDisclViewer(scwin.gAnsAcptNo, 'R');
    } else if (colid == "FINAL") {
        var url = "/dsclmgt/ULDSTF30202.gfm";
        var winTitle = "조회공시 답변관리";
        await $c.frame.CreateFrame("REQ_ANS" + scwin.gReqAcptNo, url, winTitle, 100, 10, 560, 290, "window", 0, 0, true);
    }
};
scwin.btn_New_onclick = async function() {
    var url = "/dsclmgt/ULDSTF30203.gfm";
    var winTitle = "조회공시 답변연결";
    await $c.frame.CreateFrame("REQ_ANS_NEW" + scwin.gReqAcptNo, url, winTitle, 50, 10, 810, 450 + 30, "window", 0, 0, true);
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    fn_GetParentValue();

    // 가우스헤더 셋팅
    dts_inquiryans_info.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=INQDISCLSANSLIST_INOUT";
    dts_inquiryans_info.reset();

    //  정보 읽어오기
    fn_Search();
};
